import{d as r,C as n,o as d,c as g,a3 as t,E as e,j as s,a as c}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十九章","description":"《正易心法》第十九章——一卦之中，凡具八卦：正（上下二体）、伏（二体从变）、互（二互体）、参（二互体参合）四类共八卦，及一卦八变之循环，是全书读卦技术的最高综合。","frontmatter":{"title":"正易心法·第十九章","description":"《正易心法》第十九章——一卦之中，凡具八卦：正（上下二体）、伏（二体从变）、互（二互体）、参（二互体参合）四类共八卦，及一卦八变之循环，是全书读卦技术的最高综合。","category":"guide","aliases":["正易心法第十九章","一卦之中凡具八卦","正伏互参"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-19.md","filePath":"yijing/zheng-yi-xin-fa/chapter-19.md","lastUpdated":1790647676000}'),h={name:"yijing/zheng-yi-xin-fa/chapter-19.md"},v=r({...h,setup(u){const i=[{id:"z19-01",label:"一、一卦具八卦",showLabel:!0,sentences:[["一卦之中，凡具八卦。有正有伏，有互有参。"]],note:["一个卦之中，总共具备八个卦：有正卦、有伏卦、有互卦、有参卦。（**这是第八、第九章「纵横施设」的完整升级版**：第八章给出六种施设的总纲，本章把其中的「正、伏、互、参」四类合起来数，恰好是一卦含八卦。）"]},{id:"z19-02",label:"二、正伏互参",showLabel:!0,sentences:[["正谓上下二体也，伏谓二体从变也，互谓一卦有二互体也，参谓二互体参合也。"]],note:["正，是指上下两个卦体；伏，是指上下两个卦体各自阴阳全反所得的卦；互，是指一卦中有两个互体（下互取二三四爻，上互取三四五爻）；参，是指两个互体参合为一个新卦。（四类的定义一次说清：**正是本卦的上下两半，伏是它们的错卦，互是中间四爻的两个三爻组，参是把两个互体合成一个六爻卦。**）"]},{id:"z19-03",label:"三、与本卦凡八",showLabel:!0,sentences:[["与本卦凡八，是谓一卦具八卦也。"]],note:["加上本卦共八个——这就是「一卦具八卦」。（数目很清楚：**正 2 + 伏 2 + 互 2 + 参 1 + 本卦 1 = 8**。第十九章比第九章多出的是「参卦」：互体只是三爻卦，参卦把它们合成为完整的六爻卦，**将互体的信息「完整化」**。）"]},{id:"z19-04",label:"四、一卦自有八变",showLabel:!0,sentences:[["然一卦何以具八卦？盖一卦自有八变，如乾一变姤，二变遁，三变否，四变观，五变剥，六变晋，七变大有，八变复乾是也。"]],note:["然而一个卦为什么能具备八个卦？因为一个卦自然有八种变化。比如乾卦：一变为姤，二变为遁，三变为否，四变为观，五变为剥，六变为晋，七变为大有，八变回复为乾。（**关键是这八个卦正好是乾宫八卦**——与第三十一章「八宫八变」、第三十九章「归魂复变」完全对应。静态的「一卦具八卦」，就是动态的「一卦八变」在某一时刻的截面。**就像一粒种子（静）具备整棵树的信息，也（动）经历发芽生长开花结果。**）"]},{id:"z19-05",label:"五、庄子变化链",showLabel:!0,sentences:[["因其所然，以见天地万物理无不通也。《庄子》论久竹生青宁，青宁生程，程生马，马生人，人死反入于",{text:"机",glossary:"ji"},"，万物皆出于机入于机，其一节论变化之理，无所不通如此。"]],note:["由此可见，天地万物的道理无所不通。《庄子》论述：老竹生青宁（虫），青宁生程，程生马，马生人，人死后又回归造化之机——万物都从造化之机中来，又回到造化之机中去。这一节论述变化之理，无所不通，正是如此。（**这是本书第三次引道家**。《庄子》说「万物皆出于机，入于机」＝万卦皆出于乾坤、入于乾坤。**麻衣引《庄子》的深意：道理是相通的，不必执着门派**——「天地万物理无不通」。）"]}],p=[{id:"ji",term:"机",pinyin:"jī",meaning:"造化之机，生命的根源。《庄子》「万物皆出于机，入于机」——从造化之机中来，回到造化之机中去。"}];return(b,a)=>{const l=n("DaoTextReading"),o=n("DaoKeywordCards");return d(),g("div",null,[a[0]||(a[0]=t("",27)),e(l,{colophon:"凡具八卦 · 正伏互参 · 一卦八变 · 出于机入于机",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十九章原文",sections:i,glossary:p}),a[1]||(a[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),a[2]||(a[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[c("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"正（上下二体）",pinyin:["zhèng"],meaning:"本卦的上卦与下卦——重卦的两个三爻组，是最直观的一层。"},{term:"伏（二体从变）",pinyin:["fú"],meaning:"上下二体各自阴阳全反所得的卦（错卦），共两个。"},{term:"互（二互体）",pinyin:["hù"],meaning:"下互取二三四爻、上互取三四五爻，各得一个三爻卦。"},{term:"参（二互体参合）",pinyin:["cān"],meaning:"本章新增：将下互与上互合并为一个完整六爻卦，使互体的信息「完整化」。"},{term:"一卦八变",pinyin:["bā","biàn"],meaning:"乾→姤→遁→否→观→剥→晋→大有→复乾。与第三十一章「八宫八变」一致，即一卦的动态展开。"},{term:"出于机，入于机",pinyin:["chū","yú"],meaning:"《庄子》语。万物出于造化之机、入于造化之机——即万卦出于乾坤、入于乾坤。"}]}),a[3]||(a[3]=t("",25))])}}});export{y as __pageData,v as default};
